import {bsMonths,numberWords} from './nepal-data.mjs';
import {dateUTC} from '../core.mjs';
const epoch=Date.UTC(1943,3,14),years=Object.keys(bsMonths).map(Number).sort((a,b)=>a-b),starts=[0];
for(const y of years)starts.push(starts.at(-1)+bsMonths[y].reduce((a,b)=>a+b,0));
export const devanagari=s=>String(s).replace(/\d/g,d=>'०१२३४५६७८९'[+d]);
export const ascii=s=>String(s).replace(/[०-९]/g,d=>String('०१२३४५६७८९'.indexOf(d)));
const need=(ok,m)=>{if(!ok)throw Error(m);};
export function bsToAD(value){const match=ascii(value).match(/^(\d{4})-(\d{1,2})-(\d{1,2})$/);need(match,'Use a BS date as YYYY-MM-DD.');const y=+match[1],m=+match[2],d=+match[3],months=bsMonths[y];need(months&&m>=1&&m<=12&&d>=1&&d<=months[m-1],'Use a valid BS date between 2000-01-01 and 2090-12-30.');const days=starts[y-2000]+months.slice(0,m-1).reduce((a,b)=>a+b,0)+d-1;return new Date(epoch+days*86400000).toISOString().slice(0,10);}
export function adToBS(value){const offset=Math.round((dateUTC(value)-epoch)/86400000);need(offset>=0&&offset<starts.at(-1),'Supported AD range: 1943-04-14 through 2034-04-13.');const yi=starts.findIndex((s,i)=>offset>=s&&offset<starts[i+1]),y=years[yi];let day=offset-starts[yi],m=0;while(day>=bsMonths[y][m]){day-=bsMonths[y][m];m++;}return `${y}-${String(m+1).padStart(2,'0')}-${String(day+1).padStart(2,'0')}`;}
export function nepaliNumberWords(input,currency=false){const raw=ascii(input).replace(/,/g,'').trim(),m=raw.match(/^(-?)(\d{1,15})(?:\.(\d{1,8}))?$/);need(m,'Enter up to 15 integer digits and up to 8 decimal digits.');if(currency)need(!m[3]||m[3].length<=2,'Rupee amounts support at most two paisa digits.');const value=BigInt(m[2]),words=numberWords.words||numberWords;function spell(x){if(x<100n)return words[Number(x)];const units=[[10000000000000n,'नील'],[100000000000n,'खर्ब'],[1000000000n,'अर्ब'],[10000000n,'करोड'],[100000n,'लाख'],[1000n,'हजार'],[100n,'सय']];for(const [base,label]of units)if(x>=base)return spell(x/base)+' '+label+(x%base?' '+spell(x%base):'');}const sign=m[1]&&(value>0n||Number(m[3]))?'ऋण ':'';if(currency){const paisa=Number((m[3]||'').padEnd(2,'0'));return sign+spell(value)+' रुपैयाँ'+(paisa?' '+words[paisa]+' पैसा':' मात्र');}return sign+spell(value)+(m[3]?' दशमलव '+[...m[3]].map(x=>words[+x]).join(' '):'');}
export function nebBand(percent){for(const [min,grade,point]of [[90,'A+',4],[80,'A',3.6],[70,'B+',3.2],[60,'B',2.8],[50,'C+',2.4],[40,'C',2],[35,'D',1.6]])if(percent>=min)return{grade,point};return{grade:'NG',point:null};}
export function nebGrades(input){const components=[];for(const line of input.trim().split(/\n/).filter(Boolean)){const a=line.split('|').map(x=>x.trim());need(a.length===7&&a[0]&&a.slice(1).every(x=>x!==''&&Number.isFinite(+x)&&+x>=0),'Use subject | theory marks | theory max | theory credits | internal marks | internal max | internal credits.');const [name,tm,tx,tc,im,ix,ic]=[a[0],...a.slice(1).map(Number)];need(tx>0&&tc>0&&tm<=tx&&im<=ix&&(ix>0?ic>0:ic===0),'Check component maximum marks, marks earned and actual credit weights.');const t=nebBand(tm/tx*100);components.push({subject:name,component:'Theory',percent:tm/tx*100,...t,credits:tc,meetsMinimum:tm/tx*100>=35});if(ix){const i=nebBand(im/ix*100);components.push({subject:name,component:'Internal',percent:im/ix*100,...i,credits:ic,meetsMinimum:im/ix*100>=40});}}need(components.length>=1&&components.length<=40,'Use 1–20 subject rows.');const pass=components.every(c=>c.meetsMinimum),credits=components.reduce((s,c)=>s+c.credits,0),gpa=pass?components.reduce((s,c)=>s+c.credits*c.point,0)/credits:null;return{components,pass,credits,gpa};}
